terSpacing') {\n    state.letterSpacing = nextInCycle(LETTER_SPACING_OPTIONS, state.letterSpacing);\n    return;\n  }\n  if (field === 'textAlign') {\n    state.textAlign = nextInCycle(ALIGN_OPTIONS, state.textAlign);\n    return;\n  }\n  if (field === 'readingMask') {\n    state.readingMask = !state.readingMask;\n    return;\n  }\n  if (field === 'autoCC') {\n    state.autoCC = !state.autoCC;\n    return;\n  }\n  if (field === 'reduceMotion') {\n    state.reduceMotion = !state.reduceMotion;\n    return;\n  }\n  if (field === 'cursorLarge') {\n    state.cursorLarge = !state.cursorLarge;\n    return;\n  }\n  if (field === 'dyslexiaFriendly') {\n    state.dyslexiaFriendly = !state.dyslexiaFriendly;\n    return;\n  }\n  if (field === 'readOnClick') {\n    state.readOnClick = nextInCycle(READ_CLICK_MODES, state.readOnClick);\n  }\n}\n\n/**\n *\n * @param {Object} cfg\n * @param {String} field\n */\nfunction getFieldLabel(cfg, field) {\n  if (field === 'fontStep') {\n    return t(cfg, 'fontSize');\n  }\n  if (field === 'theme') {\n    return t(cfg, 'theme');\n  }\n  if (field === 'saturation') {\n    return t(cfg, 'saturation');\n  }\n  if (field === 'letterSpacing') {\n    return t(cfg, 'letterSpacing');\n  }\n  if (field === 'textAlign') {\n    return t(cfg, 'textAlign');\n  }\n  if (field === 'readingMask') {\n    return t(cfg, 'readingMask');\n  }\n  if (field === 'autoCC') {\n    return t(cfg, 'autoCC');\n  }\n  if (field === 'reduceMotion') {\n    return t(cfg, 'reduceMotion');\n  }\n  if (field === 'cursorLarge') {\n    return t(cfg, 'cursorLarge');\n  }\n  if (field === 'dyslexiaFriendly') {\n    return t(cfg, 'dyslexiaFriendly');\n  }\n  if (field === 'readOnClick') {\n    return t(cfg, 'readOnClick');\n  }\n  return field;\n}\n\n/**\n *\n * @param {Object} cfg\n * @param {String} field\n * @param {Object} state\n */\n/**\n * Resolve the display label for a given settings field.\n *\n * @param {Object} cfg Widget configuration.\n * @param {String} field Field identifier.\n * @param {Object} state Current settings state.\n * @returns {String} Localised display label.\n */\nfunction getFieldValueLabel(cfg, field, state) {\n  if (field === 'fontStep') {\n    return 'x' + String(state.fontStep + 1);\n  }\n  if (field === 'theme') {\n    return themeValueLabel(cfg, state);\n  }\n  if (field === 'saturation') {\n    return saturationValueLabel(cfg, state);\n  }\n  if (field === 'letterSpacing') {\n    return state.letterSpacing === 'wide' ? t(cfg, 'lsWide') : t(cfg, 'lsNormal');\n  }\n  if (field === 'textAlign') {\n    return textAlignValueLabel(cfg, state);\n  }\n  if (field === 'readOnClick') {\n    return readClickValueLabel(cfg, state);\n  }\n  var boolFields = {\n    readingMask: 'readingMask',\n    autoCC: 'autoCC',\n    reduceMotion: 'reduceMotion',\n    cursorLarge: 'cursorLarge',\n    dyslexiaFriendly: 'dyslexiaFriendly',\n  };\n  if (Object.prototype.hasOwnProperty.call(boolFields, field)) {\n    return state[field] ? t(cfg, 'on') : t(cfg, 'off');\n  }\n  return '';\n}\n\n/**\n * Resolve the theme display label.\n *\n * @param {Object} cfg Widget configuration.\n * @param {Object} state Current settings state.\n * @returns {String} Localised theme label.\n */\nfunction themeValueLabel(cfg, state) {\n  if (state.theme === 'high-contrast') {\n    return t(cfg, 'themeHC');\n  }\n  if (state.theme === 'invert') {\n    return t(cfg, 'themeInvert');\n  }\n  return t(cfg, 'themeDefault');\n}\n\n/**\n * Resolve the saturation display label.\n *\n * @param {Object} cfg Widget configuration.\n * @param {Object} state Current settings state.\n * @returns {String} Localised saturation label.\n */\nfunction saturationValueLabel(cfg, state) {\n  if (state.saturation === 'low') {\n    return t(cfg, 'satLow');\n  }\n  if (state.saturation === 'high') {\n    return t(cfg, 'satHigh');\n  }\n  if (state.saturation === 'desaturate') {\n    return t(cfg, 'satDesaturate');\n  }\n  return t(cfg, 'satDefault');\n}\n\n/**\n * Resolve the text alignment display label.\n *\n * @param {Object} cfg Widget configuration.\n * @param {Object} state Current settings state.\n * @returns {String} Localised alignment label.\n */\nfunction textAlignValueLabel(cfg, state) {\n  if (state.textAlign === 'center') {\n    return t(cfg, 'taCenter');\n  }\n  if (state.textAlign === 'justify') {\n    return t(cfg, 'taJustify');\n  }\n  return t(cfg, 'taStart');\n}\n\n/**\n * Resolve the read-on-click speed display label.\n *\n * @param {Object} cfg Widget configuration.\n * @param {Object} state Current settings state.\n * @returns {String} Localised speed label.\n */\nfunction readClickValueLabel(cfg, state) {\n  if (state.readOnClick === 'fast') {\n    return t(cfg, 'rsFast');\n  }\n  if (state.readOnClick === 'slow') {\n    return t(cfg, 'rsSlow');\n  }\n  if (state.readOnClick === 'normal') {\n    return t(cfg, 'rsNormal');\n  }\n  return t(cfg, 'rsOff');\n}\n\n/**\n * Resolve the icon SVG for a given settings field.\n *\n * @param {String} field Field identifier.\n * @param {Object} state Current settings state.\n * @returns {String} SVG markup for the current value.\n */\nfunction getFieldIconSvg(field, state) {\n  var resolvers = {\n    fontStep: function() {\n      return (\n        '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 19l4-12 4 12\"/><path d=\"M5.4 15h5.2\"/>' +\n        '<path d=\"M14 7h6\"/><path d=\"M17 7v12\"/></svg>'\n      );\n    },\n    theme: function() {\n      return themeIconSvg(state);\n    },\n    saturation: function() {\n      return saturationIconSvg(state);\n    },\n    letterSpacing: function() {\n      return (\n        '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 17l3-10 3 10\"/><path d=\"M6 14h4\"/>' +\n        '<path d=\"M14 12h6\"/><path d=\"M14 9l-2 3 2 3\"/><path d=\"M20 9l2 3-2 3\"/></svg>'\n      );\n    },\n    textAlign: function() {\n      return textAlignIconSvg(state);\n    },\n    readingMask: function() {\n      if (state.readingMask) {\n 